def product_except_self(nums):
    n = len(nums)
    pre, suf = [1] * n, [1] * n
    for i in range(1, n):
        pre[i] = pre[i - 1] * nums[i - 1]
    for i in range(n - 2, -1, -1):
        suf[i] = suf[i + 1] * nums[i + 1]
    return [pre[i] * suf[i] for i in range(n)]

